  "teamGenerator.whatHappens": "What happens?",
  "teamGenerator.whatHappensText": "When you choose “Generate teams” in a session, strikr evaluates thousands of complete splits depending on participant count. The best option is then further improved with direct player swaps.",
  "teamGenerator.categoriesStrength": "Categories & strength:",
  "teamGenerator.categoriesStrengthText": "Categories can represent playing levels; individual strength from 1–5 is then used for fine tuning.",
  "teamGenerator.keepersPositions": "Goalkeepers & positions:",
  "teamGenerator.keepersPositionsText": "Goalkeepers are distributed separately, then outfield players are balanced by position where possible.",
  "teamGenerator.fineTune": "Fine tuning:",
  "teamGenerator.fineTuneText": "After finding the best complete split, strikr tests direct player swaps and keeps them only when overall balance improves.",
  "teamGenerator.balanceQuestion": "What should count toward team balance?",
  "teamGenerator.individualStrength": "Individual strength",
  "teamGenerator.recommended": "RECOMMENDED",
  "teamGenerator.individualStrengthHint": "Players get a strength rating from 1–5, allowing strikr to balance two teams much more precisely.",
  "teamGenerator.categories": "Player groups / categories",
  "teamGenerator.categoriesHint": "Useful if you manage veterans, age groups or clearly different playing levels together.",
