  "categories.stronger": "Stronger: {name}",
  "categories.shortExplain": "Quick explanation",
  "categories.shortExplainText": "Do you use different groups such as veterans and age groups? Add them here. If one group is clearly stronger, mark exactly that one – strikr handles the rest.",
  "categories.whichStronger": "Which category is stronger?",
  "categories.whichStrongerText": "Order no longer matters. Simply mark the stronger sporting category among active categories. The generator rates it higher and then uses individual strength 1–5 for fine tuning.",
  "categories.onlyOneStrong": "Each club can have exactly one active category marked as stronger. If categories do not represent sporting strength for your team, you can disable categories entirely in the team generator.",
